// Connector C: text / username / known-URL discovery.
//  * knownUrls the user typed in become candidates directly (source "user_url").
//  * usernames, keywords and @handles found by OCR are turned into a few web-search queries
//    (SerpApi Google). Results are PAGES, not images: the pipeline later "expands" them by
//    opening the page and verifying the images on it against the query image.
// No sexual / "leak" search terms are generated by the engine: queries are built only from what
// the user supplied. Site-scoped variants target the platforms listed in SITE_SCOPES.
import { Candidate } from '../types';
import { config } from '../config';
import { fetchJson } from '../util/http';
import { extractHandles } from '../fingerprint/ocr';
import { DiscoveryConnector } from './types';

const SITE_SCOPES = ['reddit.com', 'x.com', 'instagram.com', 'tiktok.com', 'facebook.com'];

function buildQueries(handles: string[], keywords: string[]): string[] {
  const qs: string[] = [];
  for (const h of handles) {
    qs.push(`"${h}"`);
    for (const k of keywords.slice(0, 2)) qs.push(`"${h}" ${k}`);
  }
  if (!handles.length && keywords.length) qs.push(keywords.join(' '));
  // Site-scoped queries for the first handle only (keeps cost bounded).
  if (handles[0]) for (const s of SITE_SCOPES) qs.push(`site:${s} "${handles[0]}"`);
  return [...new Set(qs)].slice(0, config.limits.maxTextQueries);
}

export const textSearch: DiscoveryConnector = {
  name: 'text_search',
  needsPublicUrl: false,
  enabled: () => true, // known URLs work without any key

  async search(q, fp) {
    const out: Candidate[] = q.knownUrls.map((u) => ({ pageUrl: u, source: 'user_url' }));
    if (!config.keys.serpApi) return out;

    const clean = (s: string) => s.replace(/^@/, '').trim().toLowerCase();
    const handles = [...new Set([...q.usernames.map(clean), ...extractHandles(fp.ocrText)])].filter(Boolean);
    const queries = buildQueries(handles, q.keywords);

    const settled = await Promise.allSettled(
      queries.map((query) =>
        fetchJson(`https://serpapi.com/search.json?engine=google&num=10&q=${encodeURIComponent(query)}&api_key=${config.keys.serpApi}`),
      ),
    );
    for (const s of settled) {
      if (s.status !== 'fulfilled') continue;
      for (const r of s.value.organic_results ?? [])
        if (r.link) out.push({ pageUrl: r.link, thumbnailUrl: r.thumbnail, title: r.title, source: 'text_search' });
    }
    return out;
  },
};
